e}}<br><span class="text-xs">{{$hold->placed_at->format('d M Y H:i')}}</span></td><td class="px-3 py-3 font-bold">{{str($hold->status)->headline()}}</td><td class="px-3 py-3">{{$hold->release_reason?:'—'}}@if($hold->releaser)<br><span class="text-xs">{{$hold->releaser->name}} · {{$hold->released_at}}</span>@endif</td><td class="px-3 py-3">
